    "type": "SQL",
    "name": "Patients with OPD encounters between dates",
    "config": {
      "sql": "SELECT DISTINCT e.patient_id\nFROM encounter e\nINNER JOIN encounter_type et ON et.encounter_type_id = e.encounter_type\nWHERE et.uuid = 'ee4780f5-b5eb-423b-932f-00b5879df5ab'\nAND e.encounter_datetime BETWEEN :startDate AND :endDate\nAND e.voided = 0"
    }
  },
