        "name": "Patients with OPD encounters between dates",
        "config": {
          "sql": "SELECT DISTINCT e.patient_id\nFROM encounter e\nINNER JOIN encounter_type et ON et.encounter_type_id = e.encounter_type\nWHERE et.uuid = 'ee4780f5-b5eb-423b-932f-00b5879df5ab'\nAND e.encounter_datetime BETWEEN :startDate AND :endDate\nAND e.voided = 0"
        }
      },
      "columns": [
        {
          "name": "Serial No",
          "key": "serial_no",
          "dataDefinition": {
            "type": "SQL",
            "config": {
              "sql": "SELECT value_text FROM obs WHERE encounter_id IN (SELECT encounter_id FROM encounter WHERE patient_id = :patientId AND encounter_type = (SELECT encounter_type_id FROM encounter_type WHERE uuid = 'ee4780f5-b5eb-423b-932f-00b5879df5ab') AND encounter_datetime BETWEEN :startDate AND :endDate ORDER BY encounter_datetime DESC LIMIT 1) AND concept_id = 1646 AND voided = 0"
            }
          },
          "repeatResolution": {
            "strategy": "LATEST",
            "restrictToPeriod": true,
            "ignoreVoided": true
          }
        },
        {
          "name": "Name of patient",
          "key": "patient_name",
          "dataDefinition": {
            "type": "PERSON_NAME",
            "config": {
              "type": "FULL_NAME",
              "preferred": true
            }
          }
        },
        {
          "name": "Residence",
          "key": "residence",
          "dataDefinition": {
            "type": "PERSON_ADDRESS",
            "config": {
              "type": "ADDRESS_COMBINATION",
              "fields": [
                "address5",
                "address4",
                "address3"
              ],
              "separator": "\\n"
            }
          }
