            "type": "CALCULATION",
            "config": {
              "calculation": "AGE_IN_RANGE",
              "minAge": 0.08,
              "maxAge": 5,
              "onDate": ":endDate"
            }
          }
        },
        {
          "name": "Age 5-59yrs",
          "key": "age_5_59_yrs",
          "dataDefinition": {
            "type": "CALCULATION",
            "config": {
              "calculation": "AGE_IN_RANGE",
