        {
          "name": "MUAC Weight Height",
          "key": "muac_weight_height",
          "dataDefinition": {
            "type": "SQL",
            "config": {
              "sql": "SELECT CONCAT(IFNULL((SELECT value_numeric FROM obs WHERE person_id = :patientId AND concept_id = 1343 AND voided = 0 ORDER BY obs_datetime DESC LIMIT 1), ''), '\\n', IFNULL((SELECT value_numeric FROM obs WHERE person_id = :patientId AND concept_id = 5089 AND voided = 0 ORDER BY obs_datetime DESC LIMIT 1), ''), '\\n', IFNULL((SELECT value_numeric FROM obs WHERE person_id = :patientId AND concept_id = 5090 AND voided = 0 ORDER BY obs_datetime DESC LIMIT 1), ''))"
            }
