            "config": {
              "sql": "SELECT CONCAT(IFNULL((SELECT value_numeric FROM obs WHERE person_id = :patientId AND concept_id = 1342 AND voided = 0 ORDER BY obs_datetime DESC LIMIT 1), ''), '\\n', IFNULL((SELECT cn.name FROM obs o INNER JOIN concept_name cn ON o.value_coded = cn.concept_id WHERE o.person_id = :patientId AND o.concept_id = 1854 AND o.voided = 0 AND cn.locale = 'en' AND cn.concept_name_type = 'FULLY_SPECIFIED' ORDER BY o.obs_datetime DESC LIMIT 1), ''), '\\n', CASE (SELECT value_coded FROM obs WHERE person_id = :patientId AND concept_id = 164088 AND voided = 0 ORDER BY obs_datetime DESC LIMIT 1) WHEN 1115 THEN 'N' WHEN 123814 THEN 'U' END)"
